import { useState, useCallback, useMemo } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { createI18nText, migrateI18n, type I18nText } from '@/lib/i18n-text';

const STORAGE_KEY = '__app_ledlight_features_v2';
const STORAGE_VERSION = 2;

import { useRemoteDataStore } from '@/context/RemoteDataContext';

export interface IFeature {
  id: string;
  title: I18nText;
  description: I18nText;
  icon: string;
  order: number;
}

const DEFAULT_FEATURES: IFeature[] = [
  { id: '1', title: createI18nText('Direct Factory'), description: createI18nText('Own manufacturing base with full production lines'), icon: 'Factory', order: 1 },
  { id: '2', title: createI18nText('Quality Assured'), description: createI18nText('100% QC inspection before shipment'), icon: 'ShieldCheck', order: 2 },
  { id: '3', title: createI18nText('Global Export'), description: createI18nText('Export to 50+ countries worldwide'), icon: 'Globe', order: 3 },
  { id: '4', title: createI18nText('Fast Delivery'), description: createI18nText('7-15 days standard lead time'), icon: 'Clock', order: 4 },
  { id: '5', title: createI18nText('Custom OEM'), description: createI18nText('Custom logo, packaging & parameters'), icon: 'Settings', order: 5 },
  { id: '6', title: createI18nText('24/7 Support'), description: createI18nText('Professional after-sales service team'), icon: 'Headphones', order: 6 },
];

function migrateFromLegacy(raw: unknown): IFeature[] | null {
  let arr: unknown[] = [];
  if (Array.isArray(raw)) arr = raw;
  else if (raw && typeof raw === 'object' && Array.isArray((raw as { data?: unknown[] }).data))
    arr = (raw as { data: unknown[] }).data;
  if (!arr.length) return null;
  try {
    return arr.map((item, idx) => {
      const f = item as Record<string, unknown>;
      return {
        id: String(f.id ?? `feat_${idx}`),
        title: migrateI18n(f.title as string | I18nText),
        description: migrateI18n(f.description as string | I18nText),
        icon: String(f.icon ?? 'CheckCircle2'),
        order: Number(f.order ?? idx + 1),
      };
    });
  } catch {
    return null;
  }
}

function readLocalFeatures(): { features: IFeature[]; sectionImage: string } {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (
        parsed.__version === STORAGE_VERSION &&
        Array.isArray(parsed.data) &&
        parsed.data.length > 0
      ) {
        const mapped = parsed.data.map((f: Record<string, unknown>) => ({
          ...f,
          title: migrateI18n(f.title as string | I18nText | undefined),
          description: migrateI18n(f.description as string | I18nText | undefined),
        }));
        return {
          features: mapped.sort((a: IFeature, b: IFeature) => a.order - b.order),
          sectionImage: parsed.__sectionImage || '',
        };
      }
      const migrated = migrateFromLegacy(parsed);
      if (migrated && migrated.length > 0) {
        return {
          features: migrated.sort((a: IFeature, b: IFeature) => a.order - b.order),
          sectionImage: parsed.__sectionImage || '',
        };
      }
    }
  } catch {
    // ignore
  }
  return { features: DEFAULT_FEATURES, sectionImage: '' };
}

export function useFeatures(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<{ features?: IFeature[]; sectionImage?: string }>('features');
  // 🔴 同步初始化：避免首屏空数组闪烁（直接用 useState lazy init 读 localStorage）
  const initialLocal = useMemo(() => readLocalFeatures(), []);
  const [features, setFeatures] = useState<IFeature[]>(initialLocal.features);
  const [sectionImage, setSectionImage] = useState<string>(initialLocal.sectionImage);

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displayFeatures = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData.features) && remoteData.features.length > 0) {
      return remoteData.features
        .map((f) => ({
          ...f,
          title: migrateI18n(f.title),
          description: migrateI18n(f.description),
        }))
        .sort((a, b) => a.order - b.order);
    }
    return features;
  }, [preferRemote, remoteData, features]);

  const displaySectionImage = useMemo(() => {
    if (preferRemote && remoteData && remoteData.sectionImage) {
      return remoteData.sectionImage;
    }
    return sectionImage;
  }, [preferRemote, remoteData, sectionImage]);

  // displayFeatures / displaySectionImage 在上方 useMemo 中定义

  const persistWithImage = (items: IFeature[], img: string) => {
    try {
      scopedStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items, __sectionImage: img })
      );
    } catch (e) {
      logger.warn('Failed to save features: ' + String(e));
    }
  };

  const persist = (items: IFeature[]) => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      const existing = saved ? JSON.parse(saved) : {};
      scopedStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items, __sectionImage: existing.__sectionImage || '' })
      );
    } catch (e) {
      logger.warn('Failed to save features: ' + String(e));
    }
  };

  const saveFeatures = useCallback((items: IFeature[]) => {
    const sorted = [...items].sort((a, b) => a.order - b.order);
    setFeatures(sorted);
    persist(sorted);
  }, []);

  const addFeature = useCallback(
    (feature: Omit<IFeature, 'id'>) => {
      const newItem: IFeature = {
        ...feature,
        id: Date.now().toString(),
      };
      saveFeatures([...features, newItem]);
      return newItem;
    },
    [features, saveFeatures]
  );

  const updateFeature = useCallback(
    (id: string, updates: Partial<IFeature>) => {
      const updated = features.map((f) => (f.id === id ? { ...f, ...updates } : f));
      saveFeatures(updated);
    },
    [features, saveFeatures]
  );

  const deleteFeature = useCallback(
    (id: string) => {
      saveFeatures(features.filter((f) => f.id !== id));
    },
    [features, saveFeatures]
  );

  const setFeatureSectionImage = useCallback((dataUrl: string): boolean => {
    try {
      setSectionImage(dataUrl);
      const saved = scopedStorage.getItem(STORAGE_KEY);
      const parsed = saved ? JSON.parse(saved) : {};
      parsed.__sectionImage = dataUrl;
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
      window.dispatchEvent(new CustomEvent('features-section-image-change', { detail: dataUrl }));
      return true;
    } catch (e) {
      logger.warn('Failed to save feature section image: ' + String(e));
      return false;
    }
  }, []);

  const resetFeatureSectionImage = useCallback((): boolean => {
    try {
      setSectionImage('');
      const saved = scopedStorage.getItem(STORAGE_KEY);
      const parsed = saved ? JSON.parse(saved) : {};
      delete parsed.__sectionImage;
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
      window.dispatchEvent(new CustomEvent('features-section-image-change', { detail: '' }));
      return true;
    } catch (e) {
      logger.warn('Failed to reset feature section image: ' + String(e));
      return false;
    }
  }, []);

  return {
    features: displayFeatures,
    sectionImage: displaySectionImage,
    loading,
    addFeature,
    updateFeature,
    deleteFeature,
    setFeatureSectionImage,
    resetFeatureSectionImage,
    saveFeatures,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
